export const KEY='pusula.finance.v1';
export const monthIndex=m=>Number(m.slice(0,4))*12+Number(m.slice(5,7))-1;
export function addMonths(m,n){const x=monthIndex(m)+n;return `${Math.floor(x/12)}-${String(x%12+1).padStart(2,'0')}`}
export const months=(start='2026-11',n=24)=>Array.from({length:n},(_,i)=>addMonths(start,i));
export const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(new Date());
export const money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(Number(n)||0);
export const monthLabel=m=>new Date(m+'-15T12:00:00').toLocaleDateString('tr-TR',{month:'long',year:'numeric'});
export function blank(){return {version:1,income:160000,incomeLow:150000,incomeHigh:170000,records:[],payments:{},overrides:{},monthlyIncome:{},receivables:[],debts:[],updatedAt:null}}
export function effective(rec,month){return [...rec.versions].filter(v=>v.from<=month).sort((a,b)=>b.from.localeCompare(a.from))[0]}
export function rows(state,month){return state.records.map(rec=>{const v=effective(rec,month);if(!v||v.disabled)return null;const delta=monthIndex(month)-monthIndex(rec.start);if(delta<0||(rec.count>0&&delta>=rec.count))return null;const ov=state.overrides[month+'|'+rec.id]||{};if(ov.hidden)return null;const amount=Number(ov.amount??v.amount);const day=Number(ov.day??v.day)||0;const p=state.payments[month+'|'+rec.id];const paid=Number(p?.amount)||0;const lastDay=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();const date=day?month+'-'+String(Math.min(day,lastDay)).padStart(2,'0'):null;return {...rec,...v,...ov,amount,day,date,paid,remaining:Math.max(0,amount-paid),isPaid:paid>=amount&&amount>0,payment:p}}).filter(Boolean).sort((a,b)=>(a.day||99)-(b.day||99)||a.name.localeCompare(b.name,'tr'))}
export function summary(s,m){const rr=rows(s,m),total=rr.reduce((a,r)=>a+r.amount,0),paid=rr.reduce((a,r)=>a+r.paid,0),remaining=rr.reduce((a,r)=>a+r.remaining,0);const base=Number(s.monthlyIncome[m]??s.income);const inc=incomeRows(s,m);const expected=inc.reduce((a,r)=>a+Number(r.amount),0),received=inc.filter(r=>r.paid).reduce((a,r)=>a+Number(r.amount),0);return {total,paid,remaining,base,expected,received,plannedIncome:base+expected,gap:base+expected-total,baseGap:base-total,count:rr.length,done:rr.filter(r=>r.isPaid).length}}
export function debtRows(s,through='9999-12'){return s.debts.map(d=>{const paid=Object.entries(s.payments).filter(([k])=>k.split('|')[1]===d.recordId&&k.split('|')[0]<=through).reduce((a,[,p])=>a+Number(p.amount),0);const initial=d.initial===null?null:Number(d.initial);return {...d,paid,remaining:initial===null?null:Math.max(0,initial+Number(d.added||0)-paid),overpaid:initial===null?0:Math.max(0,paid-initial-Number(d.added||0))}})}
export function priorities(s,m,date=today()){return rows(s,m).filter(r=>r.remaining>0).map(r=>{const late=r.date&&r.date<date,days=r.date?Math.ceil((Date.parse(r.date+'T12:00:00')-Date.parse(date+'T12:00:00'))/86400000):null;const score=(late?1000:days!==null&&days<=7?500:0)+(r.essential?200:0)+(r.type==='Kredi'?80:0)+(r.type==='Kart'?60:0)+(r.day?32-r.day:0);const reason=late?'Vadesi geçti':days!==null&&days>=0&&days<=7?`${days===0?'Bugün':days+' gün içinde'} vadesi geliyor`:r.essential?'Zorunlu yaşam gideri':r.type==='Kredi'?'Planlı kredi taksiti':r.type==='Kart'?'Kart ödeme planı':r.day?'Yaklaşan ödeme':'Vade günü belirlenmeli';return {...r,score,reason,late}}).sort((a,b)=>b.score-a.score||(a.day||99)-(b.day||99))}
export function pay(s,m,id,amount){const r=rows(s,m).find(x=>x.id===id);if(!r)throw Error('Ödeme kaydı bulunamadı');if(!Number.isFinite(amount)||amount<0)throw Error('Geçerli tutar girin');if(amount===0)delete s.payments[m+'|'+id];else s.payments[m+'|'+id]={amount,date:today()};return s}
export function edit(s,m,id,data,scope='month'){const rec=s.records.find(x=>x.id===id);if(!rec)throw Error('Kayıt bulunamadı');if(scope==='month')s.overrides[m+'|'+id]={...(s.overrides[m+'|'+id]||{}),...data};else{const prev=effective(rec,m)||rec.versions[0];rec.versions=rec.versions.filter(v=>v.from!==m);rec.versions.push({...prev,...data,from:m})}return s}
export function validate(s){if(!s||s.version!==1||!Array.isArray(s.records)||s.records.length>1000||!Array.isArray(s.debts)||!Array.isArray(s.receivables))throw Error('Bu dosya geçerli bir Pusula yedeği değil.');const finite=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0;const ids=new Set();for(const r of s.records){if(typeof r.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(r.id)||ids.has(r.id)||!/^\d{4}-\d{2}$/.test(r.start)||!Array.isArray(r.versions)||!r.versions.length||!finite(r.count))throw Error('Ödeme kayıtları geçersiz.');ids.add(r.id);for(const v of r.versions)if(typeof v.name!=='string'||v.name.length>200||!finite(v.amount)||!Number.isInteger(v.day)||v.day<0||v.day>31||!/^\d{4}-\d{2}$/.test(v.from))throw Error('Ödeme bilgisi geçersiz.')}if(!finite(s.income)||!s.payments||!s.overrides||!s.monthlyIncome)throw Error('Bütçe bilgisi geçersiz.');for(const p of Object.values(s.payments))if(!finite(p.amount))throw Error('Ödeme tutarı geçersiz.');for(const ov of Object.values(s.overrides))if(ov.amount!==undefined&&!finite(ov.amount))throw Error('Düzenlenen tutar geçersiz.');for(const d of s.debts)if(typeof d.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(d.id)||(d.initial!==null&&!finite(d.initial))||!finite(d.added||0))throw Error('Borç bilgisi geçersiz.');for(const r of s.receivables)if(typeof r.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(r.id)||!finite(r.amount)||typeof r.name!=='string'||!/^\d{4}-\d{2}$/.test(r.month))throw Error('Gelir kaydı geçersiz.');for(const r of (s.incomeRules||[])){if(typeof r.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(r.id)||!Array.isArray(r.versions)||!finite(r.count))throw Error('Tekrarlanan gelir geçersiz.');for(const v of r.versions)if(!finite(v.amount)||typeof v.name!=='string'||!Number.isInteger(v.day)||v.day<0||v.day>31)throw Error('Gelir bilgisi geçersiz.')}return s}
export function incomeRows(s,m){const one=(s.receivables||[]).filter(r=>r.month===m).map(r=>({...r,recurring:false}));const recurring=(s.incomeRules||[]).flatMap(rec=>{const v=effective(rec,m),delta=monthIndex(m)-monthIndex(rec.start),ov=s.incomeOverrides?.[m+'|'+rec.id]||{};if(!v||v.disabled||ov.hidden||delta<0||(rec.count&&delta>=rec.count))return [];return [{...rec,...v,...ov,month:m,recurring:true,paid:!!s.incomePaid?.[m+'|'+rec.id]}]});return [...one,...recurring].sort((a,b)=>(a.day||99)-(b.day||99))}
export function editIncome(s,m,id,data,scope='month'){s.incomeOverrides??={};const rec=(s.incomeRules||[]).find(x=>x.id===id);if(!rec)throw Error('Gelir kaydı bulunamadı');if(scope==='month')s.incomeOverrides[m+'|'+id]={...(s.incomeOverrides[m+'|'+id]||{}),...data};else{const v=effective(rec,m)||rec.versions[0];rec.versions=rec.versions.filter(v=>v.from!==m);rec.versions.push({...v,...data,from:m})}return s}
export function deleteExpense(s,m,id,scope='month'){if(scope==='all')s.records=s.records.filter(r=>r.id!==id);else if(scope==='future')edit(s,m,id,{disabled:true},'future');else edit(s,m,id,{hidden:true},'month');return s}
export function deleteIncome(s,m,id,scope='month'){if((s.incomeRules||[]).some(r=>r.id===id)){if(scope==='all')s.incomeRules=s.incomeRules.filter(r=>r.id!==id);else editIncome(s,m,id,scope==='future'?{disabled:true}:{hidden:true},scope==='future'?'future':'month')}else s.receivables=s.receivables.filter(r=>r.id!==id);return s}
